{
  "objective": {
    "factors": [
      "F1_Reachability (可达性): 方案在给定硬件(4xV100)和约束(不改权重)下，是否能闭环执行'假设->实验->结论'全流程。二值变量，0/1。若为0，后续指标无意义。",
      "F2_CapabilityGap (能力缺口覆盖率): 系统实际产出结论与'可发表级'标准之间的差距缩小比例。定义为 (Baseline_Human_Effort - System_Autonomy_Effort) / Baseline_Human_Effort。需覆盖科研循环的所有环节（检索、计算、写作）。",
      "F3_Reliability (可靠性/方差): 连续运行N次科研循环中，结果一致性高于阈值（如95%置信区间内）的比例。低可靠性意味着需要大量人工重试，抵消速度优势。",
      "F4_TimeToGoal (达成时间): 从当前状态到首次稳定产出可发表级结论所需的日历时间（天/周）。包含系统搭建、调优、试运行周期。",
      "F5_TotalCost (总拥有成本): 达到F2_F3标准所需的累计资源消耗。包括电费（函数于GPU占用时长）、云端API费用（函数于Token消耗）、以及隐性的人力监督成本（小时数）。"
    ],
    "composition": "Valid = F1_Reachability; Score = (F2_CapabilityGap * F3_Reliability) / (w_t * F4_TimeToGoal + w_c * F5_TotalCost)",
    "rationale": "该函数将'不可行'作为硬门槛（乘法项），将'质量'（能力与可靠性）作为分子最大化目标，将'速度与成本'作为分母最小化目标，精准对应'性价比最高、速度最快且可靠'的多目标优化需求。"
  },
  "dimensions": [
    {
      "id": "D1",
      "name": "架构可行性与算力边界",
      "scope": "评估4xV100-16GB硬件在TP=4及特定量化配置下的理论吞吐上限、KV Cache瓶颈及并发限制，判定'不改权重'约束下27B模型能否支撑自主科研循环的基础算力需求（可行性约束）。"
    },
    {
      "id": "D2",
      "name": "自主科研闭环工程化",
      "scope": "设计Prompt工程、Hook机制及外部记忆/工具链，使模型具备假设生成、实验设计、代码执行及自我纠错的能力，弥补单一LLM在长程逻辑推理和多步规划上的固有缺陷（优劣度量-核心能力）。"
    },
    {
      "id": "D3",
      "name": "异构协同与算力卸载策略",
      "scope": "定义MacBook M1 Max与V100服务器的任务分工边界，确定哪些子任务（如轻量检索、预处理）应本地化以降低延迟，哪些重型推理必须留在GPU，以及是否引入云端API作为弹性扩展（优劣度量-效率与成本结构）。"
    },
    {
      "id": "D4",
      "name": "可靠性保障与质量控制机制",
      "scope": "建立针对'可发表级'输出的验证协议，包括自动化单元测试、交叉验证、人工抽查反馈回路的设计，以量化并控制幻觉率与逻辑错误率，确保结果的可复现性（优劣度量-方差控制）。"
    },
    {
      "id": "D5",
      "name": "迭代路径与收敛动力学",
      "scope": "规划从当前基线到目标状态的阶段性里程碑，分析每次迭代（提示词优化、工具集成）对整体性能的边际贡献，识别收敛瓶颈及必要的非线性突破点（横切因子-时间与演化）。"
    },
    {
      "id": "D6",
      "name": "不确定性管理与黑盒探测",
      "scope": "识别当前认知盲区（如具体模型在特定科研领域的基准缺失、V100长期高负载的热稳定性数据），制定低成本试探性实验方案以消除关键假设的不确定性（横切因子-风险与信息增益）。"
    }
  ]
}

